update.foreach:
UPDATE safety_black_message
SET
id_photo = #{item.idPhoto,jdbcType=VARCHAR},
life_photo = #{item.lifePhoto,jdbcType=VARCHAR}
WHERE id = #{item.id,jdbcType=VARCHAR}

mapper.select:
SELECT smb1.id, smb1.company_name, smb1.emp_name, smb1.card_no, smb1.phone_no, smb1.id_card_no, smb1.emp_type, smb1.car_no, smb1.operator, smb1.create_time, smb1.update_time, smb1.remark, smb1.delete_falg, smb1.source, smb1.state, smb1.position_type, smb1.position_code, smb1.id_photo, smb1.life_photo FROM safety_black_message smb1 RIGHT JOIN ( SELECT id_card_no, MAX(update_time) AS max_update_time FROM safety_black_message where id_card_no in
#{item}
GROUP BY id_card_no ) smb2 ON smb1.id_card_no = smb2.id_card_no AND smb1.update_time = smb2.max_update_time order by smb1.id DESC
